/**
 * @name WhisperMeALoveSong
 * @author Antigravity
 * @version 3.5.0
 * @description Sasayaku You ni Koi wo Utau — Minimalist Smooth Pink Theme with Voice Call UI & Profile Popouts
 * @source https://github.com/BetterDiscord/BetterDiscord
 */

@import url('https://fonts.googleapis.com/css2?family=Quicksand:wght@500;600;700&display=swap');

:root {
    /* Theme Core - Minimalist Pastel Pink (No Neon, Anti-Lag) */
    --anime-bg: url("data:image/jpeg;base64,");
    --anime-bg-brightness: 0.85;
    --anime-dark-tint: rgba(14, 10, 16, 0.45);
    
    /* Pink Palette */
    --anime-pink-primary: #f472b6;
    --anime-pink-soft: #fce7f3;
    --anime-pink-border: rgba(244, 114, 182, 0.18);
    --anime-pink-hover: rgba(244, 114, 182, 0.08);
    --anime-pink-active: rgba(244, 114, 182, 0.15);
    --anime-speaking: #ff85a2;
    
    /* Flat Translucent Panels (Zero Lag, No Heavy Blur) */
    --panel-chat-bg: rgba(18, 14, 22, 0.72);
    --panel-sidebar-bg: rgba(20, 16, 24, 0.80);
    --panel-guilds-bg: rgba(15, 12, 18, 0.82);
    --panel-user-bg: rgba(24, 18, 28, 0.88);
    --panel-voice-bg: rgba(24, 18, 28, 0.75);
    
    /* Geometry */
    --top-spacing: 14px;
    --panel-radius: 12px;
    --app-font: 'Quicksand', 'Nunito', 'gg sans', sans-serif;
}

/* ==========================================================
   1. GLOBAL & FONT OPTIMIZATION (ANTI-LAG)
   ========================================================== */
body, #app-mount, input, textarea, button, select {
    font-family: var(--app-font) !important;
}

/* Breathing Room From Top (Jarak Dari Atas) */
#app-mount {
    padding-top: var(--top-spacing) !important;
    box-sizing: border-box !important;
}

/* Complete Shadow & Neon Glow Removal (NO LAG) */
*, *::before, *::after {
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
}

/* ==========================================================
   2. LIGHTWEIGHT ANIME BACKGROUND
   ========================================================== */
#app-mount::before,
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-image: var(--anime-bg);
    background-position: center center;
    background-size: cover;
    background-repeat: no-repeat;
    pointer-events: none;
    z-index: -2;
}

#app-mount::after,
body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-color: var(--anime-dark-tint);
    pointer-events: none;
    z-index: -1;
}

/* Transparent Base Layers */
html, body, #app-mount,
[class*="appAsidePanelWrapper"],
[class*="notAppAsidePanel"],
[class*="app_"],
[class*="bg_"],
.bg__960e4 {
    background: transparent !important;
}

/* ==========================================================
   3. MINIMALIST PANELS (NO SHADOW, CRISP 1PX PINK BORDER)
   ========================================================== */

/* Server List */
nav[class*="guilds_"],
[class*="guilds_"] {
    margin: 4px 4px 8px 8px !important;
    border-radius: var(--panel-radius) !important;
    background-color: var(--panel-guilds-bg) !important;
    border: 1px solid var(--anime-pink-border) !important;
}

/* Channels Sidebar */
[class*="sidebar_"] {
    margin: 4px 4px 8px 4px !important;
    border-radius: var(--panel-radius) !important;
    background-color: var(--panel-sidebar-bg) !important;
    border: 1px solid var(--anime-pink-border) !important;
    overflow: hidden !important;
}

/* Chat Viewport */
[class*="chat_"] {
    margin: 4px 8px 8px 4px !important;
    border-radius: var(--panel-radius) !important;
    background-color: var(--panel-chat-bg) !important;
    border: 1px solid var(--anime-pink-border) !important;
    overflow: hidden !important;
}

[class*="chatContent_"] {
    background: transparent !important;
}

/* Members List */
[class*="membersWrap_"] {
    margin: 4px 8px 8px 4px !important;
    border-radius: var(--panel-radius) !important;
    background-color: var(--panel-sidebar-bg) !important;
    border: 1px solid var(--anime-pink-border) !important;
    overflow: hidden !important;
}

[class*="members_"] {
    background: transparent !important;
}

/* User Bottom Left Panel */
[class*="panels_"] {
    margin: 6px 8px 8px 8px !important;
    border-radius: 14px !important;
    background-color: var(--panel-user-bg) !important;
    border: 1px solid var(--anime-pink-border) !important;
}

/* ==========================================================
   4. FIXED CHAT PROFILES & CLEAN MESSAGE ALIGNMENT
   ========================================================== */
[class*="message__"] {
    background: transparent !important;
    border-radius: 8px !important;
    margin: 1px 12px !important;
    border: 1px solid transparent !important;
    transition: background 0.12s ease !important;
}

/* Subtle Minimalist Message Hover */
[class*="message__"]:hover {
    background-color: var(--anime-pink-hover) !important;
    border-color: rgba(244, 114, 182, 0.12) !important;
}

/* Mentioned Message */
[class*="message__"][class*="mentioned_"] {
    background-color: var(--anime-pink-active) !important;
    border-left: 3px solid var(--anime-pink-primary) !important;
}

/* Fix Profile Avatar: Crisp Rounded Shape & Proper Position */
[class*="avatar__"] {
    border-radius: 50% !important;
    border: 1.5px solid rgba(244, 114, 182, 0.40) !important;
    box-sizing: border-box !important;
}

[class*="avatar__"]:hover {
    border-color: var(--anime-pink-primary) !important;
}

/* Usernames - Soft Pastel Pink */
[class*="username__"],
[class*="username_"] {
    font-weight: 700 !important;
    color: var(--anime-pink-soft) !important;
}

/* Timestamps */
[class*="timestamp__"],
[class*="timestamp_"] {
    color: rgba(255, 255, 255, 0.45) !important;
    font-size: 0.75rem !important;
}

/* ==========================================================
   5. VOICE CALL & VOICE CHANNELS UI (ENHANCED & PINK)
   ========================================================== */

/* Voice Status Bar (Bottom Left) */
[class*="container_e131a9"],
[class*="wrapper_e131a9"] {
    background: rgba(26, 18, 30, 0.92) !important;
    border-top: 1px solid var(--anime-pink-border) !important;
    padding: 6px 10px !important;
}

[class*="rtcConnectionStatus_"] {
    color: var(--anime-pink-primary) !important;
    font-weight: 700 !important;
}

/* Voice Participant Rows in Sidebar */
[class*="voiceUser_"] {
    border-radius: 8px !important;
    margin: 1px 4px !important;
    transition: background 0.12s ease !important;
}

[class*="voiceUser_"]:hover {
    background-color: var(--anime-pink-hover) !important;
}

/* Speaking Indicator (Custom Color Ring) */
[class*="avatarSpeaking_"],
[class*="speaking_"] {
    box-shadow: 0 0 0 2px var(--anime-speaking) !important;
    border-radius: 50% !important;
}

/* Call Viewport / Video Grid / Stage */
[class*="callContainer_"],
[class*="root_bfe55a"],
[class*="wrapper_cb9592"] {
    background: transparent !important;
}

/* Participant Video / Voice Tiles */
[class*="tile_"],
[class*="tile__"] {
    background-color: var(--panel-voice-bg) !important;
    border-radius: 16px !important;
    border: 1px solid var(--anime-pink-border) !important;
    overflow: hidden !important;
    transition: border-color 0.2s ease !important;
}

/* Speaking Tile Highlight */
[class*="tile_"]:has([class*="speaking_"]),
[class*="tile__"]:has([class*="speaking_"]) {
    border-color: var(--anime-speaking) !important;
}

/* Participant Name Pill */
[class*="overlayTitle_"],
[class*="indicators_"] {
    background: rgba(18, 14, 22, 0.85) !important;
    border-radius: 10px !important;
    border: 1px solid var(--anime-pink-border) !important;
    padding: 2px 8px !important;
    color: var(--anime-pink-soft) !important;
}

/* Floating Bottom Controls in Call */
[class*="bottomControls_"] {
    background: rgba(20, 15, 24, 0.92) !important;
    border-radius: 28px !important;
    border: 1px solid var(--anime-pink-border) !important;
    padding: 6px 14px !important;
}

[class*="bottomControls_"] button[class*="controlButton_"],
[class*="centerButton_"] {
    border-radius: 50% !important;
    background-color: rgba(36, 28, 42, 0.85) !important;
    transition: background 0.15s ease !important;
}

[class*="bottomControls_"] button[class*="controlButton_"]:hover,
[class*="centerButton_"]:hover {
    background-color: var(--anime-pink-primary) !important;
    color: #111218 !important;
}

/* Disconnect Call Red Button */
[class*="controlButton_"][class*="red_"] {
    background-color: #f43f5e !important;
    color: white !important;
}

/* ==========================================================
   6. USER PROFILE POPOUT & MODAL (BEAUTIFIED PROFILE UI)
   ========================================================== */

/* Outer Profile Card */
[class*="userProfileOuter_"],
[class*="userPopoutOuter_"] {
    background: rgba(20, 15, 24, 0.94) !important;
    border: 1px solid var(--anime-pink-border) !important;
    border-radius: 18px !important;
    overflow: hidden !important;
}

/* Inner Profile Card Body */
[class*="userProfileInner_"],
[class*="userPopoutInner_"],
[class*="userPopoutOverlayBackground_"],
[class*="overlayBackground_"] {
    background: rgba(26, 20, 32, 0.72) !important;
    border-radius: 14px !important;
    border: 1px solid rgba(255, 255, 255, 0.05) !important;
}

/* Profile Avatar Ring */
[class*="avatarPositionNormal_"] [class*="avatar_"],
[class*="userPopoutOuter_"] [class*="avatar_"] {
    border: 2.5px solid var(--anime-pink-primary) !important;
    border-radius: 50% !important;
}

/* Profile Badges List Container */
[class*="profileBadges_"],
[class*="badgeList_"] {
    background: rgba(32, 24, 38, 0.75) !important;
    border-radius: 12px !important;
    border: 1px solid var(--anime-pink-border) !important;
    padding: 3px 8px !important;
}

/* User Roles Pills */
[class*="rolePill_"],
[class*="role_"] {
    background: rgba(255, 133, 162, 0.12) !important;
    border: 1px solid rgba(255, 133, 162, 0.28) !important;
    border-radius: 12px !important;
}

[class*="rolePill_"]:hover,
[class*="role_"]:hover {
    background: rgba(255, 133, 162, 0.22) !important;
}

/* Action Button */
[class*="userProfileOuter_"] button[class*="lookFilled_"][class*="colorBrand_"] {
    background-color: var(--anime-pink-primary) !important;
    color: #111218 !important;
    font-weight: 700 !important;
    border-radius: 12px !important;
}

/* ==========================================================
   7. OTHER UI ENHANCEMENTS (CONTEXT MENUS, EMOJI, MODALS)
   ========================================================== */

/* Right-Click Context Menus */
[role="menu"],
[class*="menu_"] {
    background: rgba(22, 17, 26, 0.96) !important;
    border: 1px solid var(--anime-pink-border) !important;
    border-radius: 12px !important;
    padding: 6px !important;
}

[role="menuitem"],
[class*="item_"][role="menuitem"] {
    border-radius: 8px !important;
    transition: background 0.12s ease !important;
}

[role="menuitem"]:hover,
[class*="item_"][role="menuitem"]:hover {
    background-color: var(--anime-pink-hover) !important;
    color: var(--anime-pink-primary) !important;
}

/* Emoji / GIF / Sticker Picker */
[class*="contentWrapper_"] {
    background: rgba(20, 15, 24, 0.95) !important;
    border: 1px solid var(--anime-pink-border) !important;
    border-radius: 16px !important;
}

/* Quick Switcher / Search Modal */
[class*="quickswitcher_"],
[class*="focusLock_"] > [class*="root_"] {
    background: rgba(20, 15, 24, 0.95) !important;
    border: 1px solid var(--anime-pink-border) !important;
    border-radius: 16px !important;
}

/* Tooltips */
[class*="tooltip_"] {
    background: rgba(26, 20, 32, 0.95) !important;
    border: 1px solid var(--anime-pink-border) !important;
    border-radius: 8px !important;
    color: var(--anime-pink-soft) !important;
}

/* Minimalist Chat Input */
[class*="channelTextArea_"],
[class*="scrollableContainer_"] {
    background-color: rgba(26, 20, 30, 0.85) !important;
    border-radius: 18px !important;
    border: 1px solid var(--anime-pink-border) !important;
    transition: border-color 0.2s ease !important;
}

[class*="channelTextArea_"]:focus-within,
[class*="scrollableContainer_"]:focus-within {
    border-color: var(--anime-pink-primary) !important;
}

/* Titlebar & Headers */
[class*="title_"][class*="container_"],
header[class*="header_"] {
    background-color: rgba(16, 12, 18, 0.65) !important;
    border-bottom: 1px solid var(--anime-pink-border) !important;
}

/* Channels Sidebar Items */
[class*="channel_"] [class*="interactive_"] {
    border-radius: 8px !important;
    margin: 1px 6px !important;
    transition: background 0.15s ease !important;
}

[class*="channel_"] [class*="interactive_"]:hover {
    background-color: var(--anime-pink-hover) !important;
}

[class*="channel_"] [class*="selected_"] [class*="interactive_"] {
    background-color: var(--anime-pink-active) !important;
    border-left: 3px solid var(--anime-pink-primary) !important;
}

/* Badges & Pills */
[class*="numberBadge_"],
[class*="unreadMentionsBar_"] {
    background-color: var(--anime-pink-primary) !important;
    color: #111218 !important;
    font-weight: 700 !important;
    border-radius: 10px !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 5px !important;
    height: 5px !important;
}
::-webkit-scrollbar-thumb {
    background-color: rgba(244, 114, 182, 0.35) !important;
    border-radius: 8px !important;
}
::-webkit-scrollbar-thumb:hover {
    background-color: var(--anime-pink-primary) !important;
}

:root {
    --brand-experiment: var(--anime-pink-primary) !important;
    --brand-500: var(--anime-pink-primary) !important;
    --accent-color: var(--anime-pink-primary) !important;
}
